    finger: { curl: [1.2, 1.4, 1.0], thumb: [0.3, 0.5, 0.4], thumbRoll: 0.6 }   // rad — ngón co nắm tay nắm (đốt gốc, giữa, ngọn); ngón cái co từng đốt; ngón cái xoay quanh hướng ngón (ước lượng)
  }
